<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Öffentliche Problemstellen – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:950px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.area{border:1px solid #e1e7ed;border-radius:10px;padding:13px}input{width:100%;box-sizing:border-box;padding:9px;border:1px solid #bac5d1;border-radius:8px;margin:4px 0}button{padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;font-weight:700}.message,.error{padding:10px;border-radius:8px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}.muted{color:#66758a}</style></head><body><main><p><a href="/community">← Community</a></p><h1>Öffentliche Problemstellen</h1><p class="muted">Koordinaten werden vergröbert. Veröffentlichung erfolgt erst nach Moderation. Es werden keine Kennzeichen angezeigt.</p><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<section class="card"><h2>Problemstelle vorschlagen</h2><form method="post" action="/community/problems"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><div class="grid"><input name="name" placeholder="Name" required><input name="city" placeholder="Ort"><input name="district" placeholder="Landkreis"><input name="state" placeholder="Bundesland"><input name="latitude" type="number" step="0.0001" placeholder="Breitengrad"><input name="longitude" type="number" step="0.0001" placeholder="Längengrad"><input name="radius_m" type="number" min="100" max="5000" value="300"></div><button type="submit">Zur Moderation einreichen</button></form></section>
<section class="card"><div class="grid"><?php foreach($areas as $a):?><div class="area"><strong><?= $e($a['name']) ?></strong><p><?= $e(trim(($a['city']??'').' '.($a['district']??''))) ?></p><small><?= $e($a['moderation_status']) ?> · <?= $e($a['status']) ?></small><?php if($a['moderation_status']==='APPROVED'):?><p><a href="/community/problems/<?= rawurlencode($a['id']) ?>">Öffnen</a></p><?php endif;?></div><?php endforeach;?></div></section>
</main></body></html>